from itertools import permutations

# Generate all permutations of 0 to 9
perms = list(permutations(range(10)))

# Filter permutations based on the given conditions
solutions = []
for perm in perms:
    if perm[0] == 0 and perm[3] == 8:
        diffs = [abs(perm[i] - perm[i+1]) for i in range(9)]
        if set(diffs) == set(range(1, 10)) and diffs[0] == 8:
            solutions.append(perm)

# Print the first solution found, or "UNSATISFIABLE" if no solution exists
if solutions:
    print(solutions[0])
else:
    print("UNSATISFIABLE")
